import React, { useCallback, useState } from 'react';
import { Box, Button, CircularProgress, Stack, Typography } from '@mui/material';
import { CloudUpload as UploadIcon, CheckCircle as CheckIcon } from '@mui/icons-material';
import { useDropzone } from 'react-dropzone';
import documentService, { SUPPORTED_DOCUMENT_ACCEPT_MAP } from '../../services/documentService';

export interface GiftDocumentUploadFieldProps {
  documentType: string;
  documentName: string;
  onUploaded: (payload: { documentUrl: string; documentName: string; documentType: string }) => void;
  disabled?: boolean;
}

export const GiftDocumentUploadField: React.FC<GiftDocumentUploadFieldProps> = ({
  documentType,
  documentName,
  onUploaded,
  disabled = false,
}) => {
  const [uploading, setUploading] = useState(false);
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const onDrop = useCallback(
    async (acceptedFiles: File[]) => {
      const file = acceptedFiles[0];
      if (!file) return;

      const validation = documentService.validateFile(file);
      if (!validation.valid) {
        setError(validation.error || 'Invalid file');
        return;
      }

      setUploading(true);
      setError(null);
      try {
        const response = await documentService.uploadDocument(file, 'other', `GIFT application: ${documentName}`, 'company', [], {
          sourceWorkflow: 'gift_application',
        });
        const url =
          (response.document as { fileUrl?: string; url?: string; _id?: string })?.fileUrl ||
          (response.document as { url?: string })?.url ||
          (response.document as { _id?: string })?._id ||
          '';
        if (!url) {
          throw new Error('Upload succeeded but no document reference was returned.');
        }
        setUploadedFileName(file.name);
        onUploaded({
          documentUrl: url,
          documentName: documentName || file.name,
          documentType: documentType || 'supporting',
        });
      } catch (err: unknown) {
        setError(err instanceof Error ? err.message : 'Upload failed');
      } finally {
        setUploading(false);
      }
    },
    [documentName, documentType, onUploaded]
  );

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: SUPPORTED_DOCUMENT_ACCEPT_MAP,
    maxFiles: 1,
    disabled: disabled || uploading,
  });

  return (
    <Box>
      <Box
        {...getRootProps()}
        sx={{
          border: '1px dashed',
          borderColor: error ? 'error.main' : isDragActive ? 'primary.main' : 'divider',
          borderRadius: 1,
          p: 2,
          textAlign: 'center',
          cursor: disabled || uploading ? 'not-allowed' : 'pointer',
          opacity: disabled ? 0.6 : 1,
          bgcolor: isDragActive ? 'action.hover' : 'background.paper',
        }}
      >
        <input {...getInputProps()} />
        {uploading ? (
          <Stack direction="row" spacing={1} alignItems="center" justifyContent="center">
            <CircularProgress size={20} />
            <Typography variant="body2">Uploading…</Typography>
          </Stack>
        ) : uploadedFileName ? (
          <Stack direction="row" spacing={1} alignItems="center" justifyContent="center">
            <CheckIcon color="success" fontSize="small" />
            <Typography variant="body2">{uploadedFileName}</Typography>
            <Button size="small" onClick={(e) => e.stopPropagation()}>
              Replace
            </Button>
          </Stack>
        ) : (
          <Stack spacing={0.5} alignItems="center">
            <UploadIcon color="action" />
            <Typography variant="body2">
              {isDragActive ? 'Drop file here' : 'Drag & drop or click to upload'}
            </Typography>
            <Typography variant="caption" color="text.secondary">
              PDF, images, or office documents
            </Typography>
          </Stack>
        )}
      </Box>
      {error ? (
        <Typography variant="caption" color="error" sx={{ mt: 0.5, display: 'block' }}>
          {error}
        </Typography>
      ) : null}
    </Box>
  );
};

export default GiftDocumentUploadField;
